function expandSnippet(body) {
  let out = "";
  let i = 0;
  while (i < body.length) {
    const char = body[i];
    if (char === "\\") {
      out += body[i + 1] ?? "";
      i += 2;
      continue;
    }
    if (char === "$" && body[i + 1] === "{") {
      let depth = 1;
      let j = i + 2;
      while (j < body.length && depth > 0) {
        if (body[j] === "\\") {
          j += 2;
          continue;
        }
        if (body[j] === "$" && body[j + 1] === "{") {
          depth++;
          j += 2;
          continue;
        }
        if (body[j] === "}") depth--;
        j++;
      }
      const inner = body.slice(i + 2, j - 1);
      const colon = inner.indexOf(":");
      const fallback = inner.slice(colon + 1);
      out += expandSnippet(fallback === inner ? "x" : fallback);
      i = j;
      continue;
    }
    if (char === "$" && /[0-9]/.test(body[i + 1] ?? "")) {
      i += 2;
      continue;
    }
    out += char;
    i++;
  }
  return out;
}
